                            {BOOKING_TYPE_INFO[stayType]?.label?.toLowerCase() ?? stayType} rate.
                          </p>
                        )}
                      <p className="text-sm text-muted-foreground">
                        Determines pricing and discount eligibility
                      </p>
                    </div>

