content.text:
'use client'

/**
 * Pricing Summary Component
 *
 * Sticky sidebar that displays real-time pricing breakdown for manual reservations.
 * Calculates all fees, discounts, and taxes based on property configuration.
 *
 * Supports both user-defined fees/discounts and legacy fields for backward compatibility.
 */

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Separator } from '@/components/ui/separator'
import { Badge } from '@/components/ui/badge'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { DollarSign, Info } from 'lucide-react'
import type { PricingConfig, RateDiscountsConfig, DepositConfig, BookingType } from '@/lib/config/types'

interface AvailableSite {
  id: string
  name: string
  site_number: string
  base_price_per_night: number
  weekly_rate_cents?: number
  monthly_rate_cents?: number
}

interface PricingSummaryProps {
  selectedSite: AvailableSite | null
  numNights: number
  stayType: BookingType
  numAdults: number
  numChildren: number
  numPets: number
  pricingConfig: PricingConfig | null
  rateDiscountsConfig: RateDiscountsConfig | null
  depositConfig: DepositConfig | null
  checkInDate?: string
  checkOutDate?: string
  /** Manually selected discount IDs (for manual trigger_type discounts) */
  selectedDiscountIds?: string[]
  /** Manually selected fee IDs (for manual trigger_type fees) */
  selectedFeeIds?: string[]
  onTotalChange?: (totalCents: number) => void
}

interface CalculatedFee {
  id: string
  title: string
  amount: number
  is_taxable: boolean
}

interface CalculatedDiscount {
  id: string
  title: string
  amount: number
  trigger_type: string
}

export function PricingSummary({
  selectedSite,
  numNights,
  stayType,
  numAdults,
  numChildren,
  numPets,
  pricingConfig,
  rateDiscountsConfig,
  depositConfig,
  checkInDate,
  checkOutDate: _checkOutDate,
  selectedDiscountIds = [],
  selectedFeeIds = [],
  onTotalChange,
}: PricingSummaryProps) {
  const formatMoney = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
    }).format(amount)
  }

  // If no site selected or no config, show placeholder
  if (!selectedSite || !pricingConfig || !rateDiscountsConfig) {
    return (
      <div className="lg:sticky lg:top-6">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="h-5 w-5" />
              Pricing Summary
            </CardTitle>
          </CardHeader>
          <CardContent>
            <Alert>
              <Info className="h-4 w-4" />
              <AlertDescription>
                Select dates and a site to see pricing breakdown
              </AlertDescription>
            </Alert>
          </CardContent>
        </Card>
      </div>
    )
  }

  // Effective stay type (match page: weekly requires 7+ nights, monthly 28+)
  const STAY_TYPE_MIN_NIGHTS: Record<BookingType, number> = {
    nightly: 1,
    weekly: 7,
    monthly: 28,
    seasonal: 28,
    long_term: 28,
  }

  const hasWeekly = (selectedSite.weekly_rate_cents ?? 0) > 0
  const hasMonthly = (selectedSite.monthly_rate_cents ?? 0) > 0

  const effectiveStayType: BookingType =
    stayType === 'nightly'
      ? numNights >= STAY_TYPE_MIN_NIGHTS.monthly
          ? (hasMonthly ? 'monthly' : hasWeekly ? 'weekly' : 'nightly')
          : numNights >= STAY_TYPE_MIN_NIGHTS.weekly
            ? (hasWeekly ? 'weekly' : 'nightly')
            : 'nightly'
      : stayType === 'monthly' && numNights >= STAY_TYPE_MIN_NIGHTS.monthly
        ? (hasMonthly ? 'monthly' : hasWeekly ? 'weekly' : 'nightly')
        : (stayType === 'monthly' || stayType === 'weekly') &&
            numNights >= STAY_TYPE_MIN_NIGHTS.weekly
          ? (hasWeekly ? 'weekly' : 'nightly')
          : stayType

  // Base subtotal and display label from effective stay type (match accordion and blue bar)
  let subtotal: number
  let basePriceLabel: string
  const nightlyRateDollars = selectedSite.base_price_per_night / 100
  switch (effectiveStayType) {
    case 'weekly': {
      const weeklyCents = selectedSite.weekly_rate_cents ?? selectedSite.base_price_per_night * 7
      const nightlyCents = selectedSite.base_price_per_night
      const fullWeeks = Math.floor(numNights / 7)
      const remainderNights = numNights % 7
      subtotal =
        (fullWeeks * weeklyCents) / 100 + (remainderNights * nightlyCents) / 100
      basePriceLabel =
        remainderNights === 0
          ? `${fullWeeks} week${fullWeeks !== 1 ? 's' : ''} (${formatMoney(weeklyCents / 100)}/week)`
          : `${fullWeeks} week${fullWeeks !== 1 ? 's' : ''} (${formatMoney(weeklyCents / 100)}) + ${remainderNights} night${remainderNights !== 1 ? 's' : ''} (${formatMoney(nightlyCents / 100)}/night)`
      break
    }
    case 'monthly': {
      const monthlyCentsRaw = selectedSite.monthly_rate_cents ?? 0

      if (monthlyCentsRaw <= 0) {
        const weeklyCents = selectedSite.weekly_rate_cents ?? selectedSite.base_price_per_night * 7
        const nightlyCents = selectedSite.base_price_per_night
        const fullWeeks = Math.floor(numNights / 7)
        const remainderNights = numNights % 7
        subtotal = (fullWeeks * weeklyCents) / 100 + (remainderNights * nightlyCents) / 100
        basePriceLabel =
          remainderNights === 0
            ? `${fullWeeks} week${fullWeeks !== 1 ? 's' : ''} (${formatMoney(weeklyCents / 100)}/week)`
            : `${fullWeeks} week${fullWeeks !== 1 ? 's' : ''} (${formatMoney(weeklyCents / 100)}) + ${remainderNights} night${remainderNights !== 1 ? 's' : ''} (${formatMoney(nightlyCents / 100)}/night)`
        break
      }

      const monthlyCents = monthlyCentsRaw
      const nightlyCents = selectedSite.base_price_per_night
      const fullMonths = Math.floor(numNights / 28)
      const remainderNights = numNights % 28
      subtotal = (fullMonths * monthlyCents) / 100 + (remainderNights * nightlyCents) / 100
      basePriceLabel =
        remainderNights === 0
          ? `${fullMonths} month${fullMonths !== 1 ? 's' : ''} (${formatMoney(monthlyCents / 100)}/month)`
          : `${fullMonths} month${fullMonths !== 1 ? 's' : ''} (${formatMoney(monthlyCents / 100)}) + ${remainderNights} night${remainderNights !== 1 ? 's' : ''} (${formatMoney(nightlyCents / 100)}/night)`
      break
    }
    default: {
      subtotal = nightlyRateDollars * numNights
      basePriceLabel = `${formatMoney(nightlyRateDollars)}/night × ${numNights} night${numNights !== 1 ? 's' : ''}`
      break
    }
  }
  const basePricePerNight = selectedSite.base_price_per_night / 100
  const totalGuests = numAdults + (numChildren || 0)

  // =====================================================
  // User-Defined Fees Calculation
  // =====================================================
  const calculatedFees: CalculatedFee[] = []
  const userDefinedFees = pricingConfig.user_defined_fees || []
  const hasUserDefinedFees = userDefinedFees.length > 0

  if (hasUserDefinedFees) {
    // Use new user-defined fees
    for (const fee of userDefinedFees) {
      if (!fee.enabled) continue

      // Check trigger conditions
      let shouldApply = false
      const triggerType = fee.trigger_type || 'always' // Default to always for backward compatibility

      switch (triggerType) {
        case 'always':
          shouldApply = true
          break
        case 'manual':
          shouldApply = selectedFeeIds.includes(fee.id)
          break
        case 'min_nights':
          shouldApply = numNights >= (fee.trigger_conditions?.min_nights ?? 0)
          break
        case 'min_guests':
          shouldApply = totalGuests >= (fee.trigger_conditions?.min_guests ?? 0)
          break
        case 'has_pets':
          shouldApply = (numPets || 0) > 0
          break
        case 'date_range':
          // Date range check - for now, just skip if no checkInDate
          if (checkInDate) {
            const check = new Date(checkInDate)
            const start = fee.trigger_conditions?.start_date ? new Date(fee.trigger_conditions.start_date) : null
            const end = fee.trigger_conditions?.end_date ? new Date(fee.trigger_conditions.end_date) : null
            shouldApply = (!start || check >= start) && (!end || check <= end)
          }
          break
      }

      if (!shouldApply) continue

      let feeAmount = 0
      switch (fee.fee_type) {
        case 'flat_amount':
          feeAmount = (fee.value_cents ?? 0) / 100
          break
        case 'percentage_of_subtotal':
          feeAmount = subtotal * (fee.value_percentage ?? 0) / 100
          break
        case 'percentage_of_total':
          // For percentage_of_total, we'll calculate after other fees are summed
          // For now, estimate based on subtotal
          feeAmount = subtotal * (fee.value_percentage ?? 0) / 100
          break
        case 'per_night':
          feeAmount = ((fee.value_cents ?? 0) / 100) * numNights
          break
        case 'per_guest':
          feeAmount = ((fee.value_cents ?? 0) / 100) * totalGuests
          break
        case 'per_guest_per_night':
          feeAmount = ((fee.value_cents ?? 0) / 100) * totalGuests * numNights
          break
      }

      if (feeAmount > 0) {
        calculatedFees.push({
          id: fee.id,
          title: fee.title,
          amount: feeAmount,
          is_taxable: fee.is_taxable,
        })
      }
    }
  } else {
    // Fall back to legacy fees
    // Extra guest fees
    const extraGuestThreshold = pricingConfig.extra_guest_threshold ?? 2
    const extraGuestFeeCents = pricingConfig.extra_guest_fee_cents ?? 0
    if (pricingConfig.extra_guest_fee_enabled && totalGuests > extraGuestThreshold && extraGuestFeeCents > 0) {
      const extraGuests = totalGuests - extraGuestThreshold
      const extraGuestFee = extraGuests * extraGuestFeeCents * numNights / 100
      calculatedFees.push({
        id: 'legacy-extra-guest',
        title: `Extra Guest Fee (${extraGuests} guests)`,
        amount: extraGuestFee,
        is_taxable: true,
      })
    }

    // Pet fees
    if ((numPets || 0) > 0 && pricingConfig.pet_fee_cents) {
      calculatedFees.push({
        id: 'legacy-pet',
        title: `Pet Fee (${numPets} ${numPets === 1 ? 'pet' : 'pets'})`,
        amount: pricingConfig.pet_fee_cents / 100,
        is_taxable: true,
      })
    }

    // Cleaning fee
    if (pricingConfig.default_cleaning_fee_cents) {
      calculatedFees.push({
        id: 'legacy-cleaning',
        title: 'Cleaning Fee',
        amount: pricingConfig.default_cleaning_fee_cents / 100,
        is_taxable: true,
      })
    }

    // Service fee
    if (pricingConfig.service_fee_type === 'percentage' && pricingConfig.service_fee_percentage) {
      const serviceFee = subtotal * (pricingConfig.service_fee_percentage / 100)
      calculatedFees.push({
        id: 'legacy-service',
        title: `Service Fee (${pricingConfig.service_fee_percentage}%)`,
        amount: serviceFee,
        is_taxable: true,
      })
    } else if (pricingConfig.service_fee_type === 'flat' && pricingConfig.service_fee_amount_cents) {
      calculatedFees.push({
        id: 'legacy-service',
        title: 'Service Fee',
        amount: pricingConfig.service_fee_amount_cents / 100,
        is_taxable: true,
      })
    } else if (pricingConfig.service_fee_type === 'per_night' && pricingConfig.service_fee_amount_cents) {
      calculatedFees.push({
        id: 'legacy-service',
        title: `Service Fee (${numNights} nights)`,
        amount: (pricingConfig.service_fee_amount_cents / 100) * numNights,
        is_taxable: true,
      })
    }
  }

  // =====================================================
  // User-Defined Discounts Calculation
  // =====================================================
  const calculatedDiscounts: CalculatedDiscount[] = []
  const userDefinedDiscounts = rateDiscountsConfig.user_defined_discounts || []
  const hasUserDefinedDiscounts = userDefinedDiscounts.length > 0

  // Helper function to check if date is in range
  const isDateInRange = (checkDate: string | undefined, startDate: string | undefined, endDate: string | undefined): boolean => {
    if (!checkDate) return false
    const check = new Date(checkDate)
    if (startDate && check < new Date(startDate)) return false
    if (endDate && check > new Date(endDate)) return false
    return true
  }

  if (hasUserDefinedDiscounts) {
    // Use new user-defined discounts
    for (const discount of userDefinedDiscounts) {
      if (!discount.enabled) continue

      // Check trigger conditions
      let shouldApply = false

      // Manual discounts are only applied if explicitly selected
      if (discount.trigger_type === 'manual') {
        shouldApply = selectedDiscountIds.includes(discount.id)
      } else {
        // Auto-triggered discounts
        switch (discount.trigger_type) {
          case 'min_nights':
            shouldApply = numNights >= (discount.trigger_conditions?.min_nights ?? 0)
            break
          case 'min_guests':
            shouldApply = totalGuests >= (discount.trigger_conditions?.min_guests ?? 0)
            break
          case 'date_range':
            shouldApply = isDateInRange(
              checkInDate,
              discount.trigger_conditions?.start_date,
              discount.trigger_conditions?.end_date
            )
            break
        }
      }

      if (!shouldApply) continue

      let discountAmount = 0
      switch (discount.discount_type) {
        case 'flat_amount':
          discountAmount = (discount.value_cents ?? 0) / 100
          break
        case 'percentage_of_subtotal':
          discountAmount = subtotal * (discount.value_percentage ?? 0) / 100
          break
        case 'percentage_of_total':
          // Estimate based on subtotal for now
          discountAmount = subtotal * (discount.value_percentage ?? 0) / 100
          break
      }

      // Apply max discount cap if set
      if (discount.max_discount_cents && discountAmount > discount.max_discount_cents / 100) {
        discountAmount = discount.max_discount_cents / 100
      }

      if (discountAmount > 0) {
        calculatedDiscounts.push({
          id: discount.id,
          title: discount.title,
          amount: discountAmount,
          trigger_type: discount.trigger_type,
        })
      }
    }
  } else {
    // Fall back to legacy discounts
    const monthlyEnabled = rateDiscountsConfig.monthly_discount_enabled ?? false
    const monthlyMinNights = rateDiscountsConfig.monthly_minimum_nights ?? 28
    const monthlyPercentage = rateDiscountsConfig.monthly_discount_percentage ?? 0
    const weeklyEnabled = rateDiscountsConfig.weekly_discount_enabled ?? false
    const weeklyMinNights = rateDiscountsConfig.weekly_minimum_nights ?? 7
    const weeklyPercentage = rateDiscountsConfig.weekly_discount_percentage ?? 0

    if (monthlyEnabled && numNights >= monthlyMinNights && monthlyPercentage > 0) {
      calculatedDiscounts.push({
        id: 'legacy-monthly',
        title: `${monthlyPercentage}% Monthly Discount`,
        amount: subtotal * (monthlyPercentage / 100),
        trigger_type: 'min_nights',
      })
    } else if (weeklyEnabled && numNights >= weeklyMinNights && weeklyPercentage > 0) {
      calculatedDiscounts.push({
        id: 'legacy-weekly',
        title: `${weeklyPercentage}% Weekly Discount`,
        amount: subtotal * (weeklyPercentage / 100),
        trigger_type: 'min_nights',
      })
    }
  }

  // =====================================================
  // Final Calculations
  // =====================================================

  // Sum up discounts
  const totalDiscountAmount = calculatedDiscounts.reduce((sum, d) => sum + d.amount, 0)
  const discountedSubtotal = subtotal - totalDiscountAmount

  // Sum up fees (both taxable and non-taxable)
  const totalFees = calculatedFees.reduce((sum, f) => sum + f.amount, 0)
  const taxableFees = calculatedFees
    .filter(f => f.is_taxable)
    .reduce((sum, f) => sum + f.amount, 0)

  // Subtotal before tax
  const subtotalBeforeTax = discountedSubtotal + totalFees

  // Tax calculation (on discounted subtotal + taxable fees)
  const taxableAmount = discountedSubtotal + taxableFees
  const taxAmount = taxableAmount * pricingConfig.tax_rate
  const taxLabel = `${pricingConfig.tax_name} (${(pricingConfig.tax_rate * 100).toFixed(2)}%)`

  // Total
  const total = subtotalBeforeTax + taxAmount
  onTotalChange?.(Math.round(total * 100))

  // Deposit calculation (if applicable)
  let depositAmount = 0
  let depositLabel = ''
  if (depositConfig && depositConfig.require_deposit && depositConfig.applies_to_booking_types?.includes(stayType)) {
    if (depositConfig.deposit_type === 'percentage' && depositConfig.deposit_percentage) {
      depositAmount = total * (depositConfig.deposit_percentage / 100)
      depositLabel = `Deposit (${depositConfig.deposit_percentage}%)`
    } else if (depositConfig.deposit_type === 'flat_amount' && depositConfig.deposit_amount_cents) {
      depositAmount = depositConfig.deposit_amount_cents / 100
      depositLabel = 'Deposit'
    } else if (depositConfig.deposit_type === 'first_night') {
      depositAmount = (basePricePerNight + (basePricePerNight * pricingConfig.tax_rate))
      depositLabel = 'Deposit (First Night)'
    }
  }

  return (
    <div className="lg:sticky lg:top-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <DollarSign className="h-5 w-5" />
            Pricing Summary
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Site info */}
          <div>
            <p className="font-medium">{selectedSite.name}</p>
            <p className="text-sm text-muted-foreground">
              Site #{selectedSite.site_number}
            </p>
          </div>

          <Separator />

          {/* Base price breakdown (weekly/monthly/nightly) */}
          <div className="space-y-2">
            <div className="flex items-center justify-between text-sm">
              <span>{basePriceLabel}</span>
              <span className="font-medium">{formatMoney(subtotal)}</span>
            </div>

            {/* Discounts */}
            {calculatedDiscounts.map((discount) => (
              <div key={discount.id} className="flex items-center justify-between text-sm text-green-600">
                <div className="flex items-center gap-2">
                  <span>{discount.title}</span>
                  {discount.trigger_type !== 'manual' && (
                    <Badge variant="secondary" className="text-xs">
                      Auto
                    </Badge>
                  )}
                </div>
                <span className="font-medium">-{formatMoney(discount.amount)}</span>
              </div>
            ))}

            {/* User-Defined Fees */}
            {calculatedFees.map((fee) => (
              <div key={fee.id} className="flex items-center justify-between text-sm">
                <span>{fee.title}</span>
                <span>{formatMoney(fee.amount)}</span>
              </div>
            ))}
          </div>

          <Separator />

          {/* Tax */}
          <div className="flex items-center justify-between text-sm">
            <span>{taxLabel}</span>
            <span>{formatMoney(taxAmount)}</span>
          </div>

          <Separator />

          {/* Total */}
          <div className="flex items-center justify-between">
            <span className="text-lg font-bold">Total</span>
            <span className="text-2xl font-bold text-primary">{formatMoney(total)}</span>
          </div>

          {/* Deposit info */}
          {depositAmount > 0 && (
            <>
              <Separator />
              <div className="bg-primary/5 rounded-lg p-3 space-y-2">
                <div className="flex items-center justify-between">
                  <span className="font-medium text-sm">{depositLabel}</span>
                  <span className="font-bold">{formatMoney(depositAmount)}</span>
                </div>
                <div className="flex items-center justify-between text-sm text-muted-foreground">
                  <span>Due at Booking</span>
                  <span>{formatMoney(depositAmount)}</span>
                </div>
                <div className="flex items-center justify-between text-sm text-muted-foreground">
                  <span>Remaining Balance</span>
                  <span>{formatMoney(total - depositAmount)}</span>
                </div>
                {depositConfig?.full_payment_required_days_before && (
                  <p className="text-xs text-muted-foreground mt-2">
                    Full payment due {depositConfig.full_payment_required_days_before} days before check-in
                  </p>
                )}
              </div>
            </>
          )}

          {/* Guest summary */}
          <div className="text-xs text-muted-foreground space-y-1">
            <div className="flex items-center justify-between">
              <span>Guests</span>
              <span>
                {numAdults} {numAdults === 1 ? 'adult' : 'adults'}
                {numChildren > 0 && `, ${numChildren} ${numChildren === 1 ? 'child' : 'children'}`}
              </span>
            </div>
            {numPets > 0 && (
              <div className="flex items-center justify-between">
                <span>Pets</span>
                <span>{numPets}</span>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

/**
 * Manual Reservation API v1
 *
 * POST /api/v1/properties/[propertyId]/reservations/manual
 *
 * Creates a manual reservation (phone/walk-in booking) with extended
 * family and vehicle information.
 */

import { type NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { success, error } from '@/lib/api/response'
import { ErrorCodes } from '@/lib/api/errors'
import { requirePropertyAccess, isDenied } from '@/lib/rbac'
import { canCreateReservationsModule } from '@/lib/dashboard/reservations-module-access'
import {
  CreateManualReservationRequestSchema,
} from '@/types/api/v1/schemas/reservations'
import { CreateManualReservationCommandHandler } from '@/modules/BookingEngine/application/commands/CreateManualReservationCommand'
import { sendBookingConfirmation } from '@/lib/email/send'
import {
  extractOpenPeriodFromPropertySettings,
  isStayWithinOpenPeriodByIsoDates,
  buildOpenPeriodBookingErrorMessage,
} from '@/lib/booking/open-period'
import { recordActivityLog } from '@/shared/activity-log/record-activity-log'

/**
 * POST /api/v1/properties/[propertyId]/reservations/manual
 *
 * Create a manual reservation for phone/walk-in bookings.
 * Supports extended data: spouse/partner, children, vehicles, evacuation contact.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ propertyId: string }> }
) {
  try {
    const { propertyId } = await params
    const supabase = await createClient()

    // Authenticate user
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser()

    if (authError || !user) {
      return error(ErrorCodes.AUTH_001, request)
    }

    // Verify property ownership (BP-4: Multi-tenant isolation)
    const { data: property, error: propertyError } = await supabase
      .from('properties')
      .select('id, name, owner_id, settings, company_id')
      .eq('id', propertyId)
      .single()

    if (propertyError || !property) {
      return error(ErrorCodes.PROP_001, request)
    }

    // RBAC: verify user has access to this property
    const access = await requirePropertyAccess(supabase, user.id, {
      propertyId,
      minimumRole: 'staff',
    })
    if (isDenied(access)) return access

    const canCreateReservation = await canCreateReservationsModule(supabase, propertyId, user.id)
    if (!canCreateReservation) {
      return error(
        ErrorCodes.AUTH_006.code,
        'You do not have permission to create manual reservation',
        ErrorCodes.AUTH_006.status,
        request,
      )
    }


    // Parse and validate request body
    const body = await request.json()
    const parsed = CreateManualReservationRequestSchema.safeParse(body)

    if (!parsed.success) {
      return error(
        ErrorCodes.VAL_001,
        request,
        { validationErrors: parsed.error.format() }
      )
    }

    const data = parsed.data

    const { openPeriodFrom, openPeriodUntil } = extractOpenPeriodFromPropertySettings(property.settings)
    if (
      !isStayWithinOpenPeriodByIsoDates(
        data.checkInDate,
        data.checkOutDate,
        openPeriodFrom,
        openPeriodUntil,
      )
    ) {
      const fromIso = openPeriodFrom?.trim()
      const untilIso = openPeriodUntil?.trim()
      const message =
        fromIso && untilIso
          ? buildOpenPeriodBookingErrorMessage(property.name, fromIso, untilIso)
          : 'Selected dates are outside the property booking season.'
      return error(ErrorCodes.VAL_001, request, { message })
    }

    // Debug: Log what we're looking for
    console.log('[Manual Reservation v1] Looking up site:', { siteId: data.siteId, propertyId })

    // Get site info for email (use service role to bypass RLS since we've verified property ownership)
    const supabaseServiceRole = createServiceRoleClient()

    // First, check if site exists at all (for debugging)
    const { data: siteCheck, error: siteCheckError } = await supabaseServiceRole
      .from('sites')
      .select('id, site_name, property_id')
      .eq('id', data.siteId)
      .is('deleted_at', null)
      .single()

    console.log('[Manual Reservation v1] Site lookup result:', { siteCheck, siteCheckError })

    if (siteCheckError || !siteCheck) {
      console.error('[Manual Reservation v1] Site not found in database:', { siteId: data.siteId, error: siteCheckError })
      return error(ErrorCodes.SITE_001, request, { message: `Site ${data.siteId} does not exist` })
    }

    // Verify site belongs to the property
    if (siteCheck.property_id !== propertyId) {
      console.error('[Manual Reservation v1] Site property mismatch:', {
        siteId: data.siteId,
        sitePropertyId: siteCheck.property_id,
        requestPropertyId: propertyId
      })
      return error(ErrorCodes.SITE_001, request, {
        message: `Site ${data.siteId} does not belong to property ${propertyId}`
      })
    }

    const site = siteCheck

    // Execute the command
    console.log('[Manual Reservation v1] Executing command handler with:', {
      siteId: data.siteId,
      propertyId,
      checkInDate: data.checkInDate,
      checkOutDate: data.checkOutDate,
      guestEmail: data.guest.email,
    })

    const handler = new CreateManualReservationCommandHandler()
    let result
    try {
      result = await handler.execute({
        ...data,
        propertyId,
      })
      console.log('[Manual Reservation v1] Command handler succeeded:', { reservationId: result.id })
      if (property.company_id) {
        await recordActivityLog(supabaseServiceRole, {
          companyId: property.company_id,
          propertyId,
          action: 'created',
          resource: 'reservation',
          userId: user.id,
          details: `Manual reservation for ${result.guestName} (confirmation ${result.confirmationNumber})`,
        })
      }
    } catch (cmdError) {
      console.error('[Manual Reservation v1] Command handler failed:', cmdError)
      throw cmdError
    }

    // Calculate nights for email
    const checkIn = new Date(data.checkInDate)
    const checkOut = new Date(data.checkOutDate)
    const numNights = Math.ceil((checkOut.getTime() - checkIn.getTime()) / (1000 * 60 * 60 * 24))

    // Send confirmation email (non-blocking)
    // Build email data conditionally (exactOptionalPropertyTypes)
    const emailData: Parameters<typeof sendBookingConfirmation>[0] = {
      guestName: result.guestName,
      guestEmail: data.guest.email,
      confirmationNumber: result.confirmationNumber,
      propertyName: property.name,
      siteName: site.site_name || `Site ${data.siteId.slice(0, 8)}`,
      checkInDate: data.checkInDate,
      checkOutDate: data.checkOutDate,
      numNights,
      numAdults: data.numAdults,
      numChildren: data.numChildren || 0,
      totalAmount: result.totalAmountCents,
      paidAmount: result.paidAmountCents,
      paymentStatus: result.paymentStatus as 'paid' | 'partial' | 'pending',
    }
    if (data.specialRequests) emailData.specialRequests = data.specialRequests

    sendBookingConfirmation(emailData).catch((err) => {
      console.error('[Manual Reservation v1] Failed to send confirmation email:', err)
    })

    // Return success response
    return success(
      {
        reservation: {
          id: result.id,
          confirmationNumber: result.confirmationNumber,
          guestName: result.guestName,
          checkInDate: result.checkInDate,
          checkOutDate: result.checkOutDate,
          totalAmountCents: result.totalAmountCents,
          paidAmountCents: result.paidAmountCents,
          status: result.status,
          paymentStatus: result.paymentStatus,
          childrenCount: result.childrenCount,
          vehiclesCount: result.vehiclesCount,
          createdAt: result.createdAt,
        },
      },
      request
    )
  } catch (err) {
    console.error('[Manual Reservation v1] Unexpected error:', err)

    // Handle specific error types
    if (err instanceof Error) {
      if (err.message.includes('not available')) {
        return error(ErrorCodes.RES_002, request, { message: err.message })
      }
      if (err.message.includes('Missing required')) {
        return error(ErrorCodes.VAL_002, request, { message: err.message })
      }
      // Return error details for debugging
      return error(ErrorCodes.SYS_001, request, {
        message: err.message,
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
      })
    }

    return error(ErrorCodes.SYS_001, request, {
      message: String(err),
    })
  }
}

/**
 * CreateManualReservationCommand
 *
 * Command to create a manual reservation (phone/walk-in booking) with
 * extended family and vehicle information.
 *
 * Handles:
 * - Core reservation creation
 * - Guest creation/lookup
 * - Spouse/partner information (stored on guest)
 * - Children information (stored per reservation)
 * - Vehicle information (stored on guest, linked to reservation)
 * - Evacuation contact (stored on reservation)
 * - Payment recording
 */

import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { createGuest, updateGuestSpouse } from '@/lib/booking/guest'
import { createReservationChildren } from '@/lib/booking/children'
import { createReservationPets } from '@/lib/booking/pets'
import { createGuestVehicles, linkVehiclesToReservation } from '@/lib/booking/vehicles'
import { checkSiteAvailability } from '@/lib/booking/availability'
import { generateConfirmationNumber } from '@/lib/booking/api'
import type { CreatePetInputData, CreateVehicleInputData } from '@/lib/booking/types'
import type {
  CreateManualReservationRequest,
  ChildInput,
  PetInput,
  VehicleInput,
} from '@/types/api/v1/schemas/reservations'

export type CreateManualReservationDto = CreateManualReservationRequest & {
  propertyId: string
}

export type ManualReservationResult = {
  id: string
  confirmationNumber: string
  guestId: string
  guestName: string
  checkInDate: string
  checkOutDate: string
  totalAmountCents: number
  paidAmountCents: number
  status: string
  paymentStatus: string
  childrenCount: number
  vehiclesCount: number
  createdAt: string
}

export class CreateManualReservationCommandHandler {
  async execute(dto: CreateManualReservationDto): Promise<ManualReservationResult> {
    const supabase = createServiceRoleClient()

    // 1. Always create a new guest record (manual bookings never reuse existing by email)
    // Build guest input conditionally to avoid undefined values (exactOptionalPropertyTypes)
    const guestInput: Parameters<typeof createGuest>[1] = {
      first_name: dto.guest.firstName,
      last_name: dto.guest.lastName,
      email: dto.guest.email,
      phone: dto.guest.phone,
    }
    if (dto.guest.address) guestInput.address = dto.guest.address
    if (dto.guest.city) guestInput.city = dto.guest.city
    if (dto.guest.state) guestInput.state = dto.guest.state
    if (dto.guest.zipCode) guestInput.zip_code = dto.guest.zipCode

    const guestResult = await createGuest(dto.propertyId, guestInput)
    if (!guestResult.success) {
      throw new Error(guestResult.error.message)
    }
    const guest = guestResult.data

    // 2. Check site availability (guard against double-booking)
    const availabilityResult = await checkSiteAvailability(
      dto.siteId,
      dto.checkInDate,
      dto.checkOutDate
    )
    if (!availabilityResult.success) {
      throw new Error(availabilityResult.error.message)
    }
    if (!availabilityResult.data) {
      throw new Error('Site is not available for the selected dates')
    }

    // 2a. Insert reservation directly using the already-created guest ID.
    const { data: reservation, error: reservationError } = await supabase
      .from('reservations')
      .insert({
        property_id: dto.propertyId,
        site_id: dto.siteId,
        guest_id: guest.id,
        confirmation_number: generateConfirmationNumber(),
        check_in_date: dto.checkInDate,
        check_out_date: dto.checkOutDate,
        num_adults: dto.numAdults,
        num_children: dto.numChildren || 0,
        num_pets: dto.numPets || 0,
        num_vehicles: dto.numVehicles || 0,
        total_amount: 0,
        paid_amount: 0,
        status: 'pending',
        payment_status: 'pending',
        source: 'phone',
        booking_type: dto.stayType || 'nightly',
        special_requests: dto.specialRequests || null,
        notes: null,
      })
      .select('*')
      .single()

    if (reservationError || !reservation) {
      const detail = reservationError
        ? `${reservationError.message} (code: ${reservationError.code})`
        : 'Unknown error'
      throw new Error(`Failed to create reservation: ${detail}`)
    }

    // 2b. Apply client-provided total when present (fixes $0 when site.base_price is unset)
    if (dto.totalAmountCents != null && dto.totalAmountCents > 0) {
      await supabase
        .from('reservations')
        .update({ total_amount: dto.totalAmountCents })
        .eq('id', reservation.id)
        .eq('property_id', dto.propertyId)
      reservation.total_amount = dto.totalAmountCents
    }

    // 3. Handle spouse/partner information (stored on guest)
    if (dto.spousePartner) {
      // Build spouse input conditionally (exactOptionalPropertyTypes)
      const spouseDbInput: Parameters<typeof updateGuestSpouse>[2] = {
        first_name: dto.spousePartner.firstName,
        last_name: dto.spousePartner.lastName,
        is_alternate_contact: dto.spousePartner.isAlternateContact,
      }
      if (dto.spousePartner.phone) spouseDbInput.phone = dto.spousePartner.phone
      if (dto.spousePartner.email) spouseDbInput.email = dto.spousePartner.email

      await updateGuestSpouse(guest.id, dto.propertyId, spouseDbInput)
    }

    // 4. Handle children information (per reservation)
    let childrenCount = 0
    if (dto.children && dto.children.length > 0) {
      // Build children input conditionally (exactOptionalPropertyTypes)
      const childrenInput = dto.children.map((child: ChildInput) => {
        const childData: { first_name: string; age?: number; date_of_birth?: string; special_needs_allergies?: string } = {
          first_name: child.firstName,
        }
        if (child.age != null) childData.age = child.age
        if (child.dateOfBirth) childData.date_of_birth = child.dateOfBirth
        if (child.specialNeedsAllergies) childData.special_needs_allergies = child.specialNeedsAllergies
        return childData
      })
      await createReservationChildren(reservation.id, dto.propertyId, childrenInput)
      childrenCount = dto.children.length
    }

    // 5. Handle pets information (per reservation)
    if (dto.pets && dto.pets.length > 0) {
      const petsInput: CreatePetInputData[] = dto.pets.map((pet: PetInput) => {
        const petData: CreatePetInputData = {
          name: pet.name,
          type: pet.type,
        }
        if (pet.breed) petData.breed = pet.breed
        if (pet.weightLbs != null) petData.weight_lbs = pet.weightLbs
        if (pet.notes) petData.notes = pet.notes
        return petData
      })

      await createReservationPets(reservation.id, dto.propertyId, petsInput)
    }

    // 6. Handle vehicle information (on guest, linked to reservation)
    let vehiclesCount = 0
    if (dto.vehicles && dto.vehicles.length > 0) {
      // Build vehicle input conditionally (exactOptionalPropertyTypes)
      const vehicleInput: CreateVehicleInputData[] = dto.vehicles.map((v: VehicleInput) => {
        const vData: CreateVehicleInputData = {
          vehicle_type: v.vehicleType,
        }
        if (v.isPrimary != null) vData.is_primary = v.isPrimary
        if (v.make) vData.make = v.make
        if (v.model) vData.model = v.model
        if (v.year != null) vData.year = v.year
        if (v.color) vData.color = v.color
        if (v.licensePlate) vData.license_plate = v.licensePlate
        if (v.licensePlateState) vData.license_plate_state = v.licensePlateState
        if (v.personalVehicleType) vData.personal_vehicle_type = v.personalVehicleType
        if (v.rvType) vData.rv_type = v.rvType
        if (v.rvLengthFeet != null) vData.rv_length_feet = v.rvLengthFeet
        if (v.rvWidthFeet != null) vData.rv_width_feet = v.rvWidthFeet
        if (v.numSlideOuts != null) vData.num_slide_outs = v.numSlideOuts
        if (v.insuranceCompany) vData.insurance_company = v.insuranceCompany
        if (v.insurancePolicyNumber) vData.insurance_policy_number = v.insurancePolicyNumber
        return vData
      })

      const vehicleResult = await createGuestVehicles(guest.id, dto.propertyId, vehicleInput)
      if (vehicleResult.success && vehicleResult.data.length > 0) {
        const vehicleIds = vehicleResult.data.map((v) => v.id)
        await linkVehiclesToReservation(reservation.id, vehicleIds)
        vehiclesCount = vehicleResult.data.length
      }
    }

    // 7. Handle evacuation contact (on reservation)
    if (dto.evacuationContact) {
      await supabase
        .from('reservations')
        .update({
          evacuation_contact_name: dto.evacuationContact.name,
          evacuation_contact_phone: dto.evacuationContact.phone,
          evacuation_contact_relationship: dto.evacuationContact.relationship || null,
        })
        .eq('id', reservation.id)
        .eq('property_id', dto.propertyId)
    }

    // 8. Handle payment
    const paidAmountCents = dto.paidAmountCents || 0
    const totalAmountCents = dto.totalAmountCents ?? reservation.total_amount
    const isFullyPaid = paidAmountCents >= totalAmountCents
    const paymentStatus = paidAmountCents > 0
      ? (isFullyPaid ? 'paid' : 'partial')
      : 'pending'

    const reservationStatus = isFullyPaid ? 'confirmed' : 'pending'

    if (paidAmountCents > 0) {
      // Update reservation payment status
      await supabase
        .from('reservations')
        .update({
          status: reservationStatus,
          payment_status: paymentStatus,
          paid_amount: paidAmountCents,
          notes: dto.notes || `Manual booking. Payment method: ${dto.paymentMethod}`,
        })
        .eq('id', reservation.id)
        .eq('property_id', dto.propertyId)

      // Create payment record
      await supabase
        .from('payments')
        .insert({
          property_id: dto.propertyId,
          reservation_id: reservation.id,
          amount: paidAmountCents,
          payment_method: dto.paymentMethod,
          payment_status: 'completed',
          processed_at: new Date().toISOString(),
          notes: `Manual payment - ${dto.paymentMethod}`,
        })
    } else {
      // Unpaid: keep status pending
      await supabase
        .from('reservations')
        .update({
          status: 'pending',
          payment_status: 'pending',
          notes: dto.notes || `Manual booking. Payment method: ${dto.paymentMode} (payment pending)`,
        })
        .eq('id', reservation.id)
        .eq('property_id', dto.propertyId)
    }

    return {
      id: reservation.id,
      confirmationNumber: reservation.confirmation_number,
      guestId: guest.id,
      guestName: `${dto.guest.firstName} ${dto.guest.lastName}`,
      checkInDate: dto.checkInDate,
      checkOutDate: dto.checkOutDate,
      totalAmountCents: reservation.total_amount,
      paidAmountCents,
      status: reservationStatus,
      paymentStatus,
      childrenCount,
      vehiclesCount,
      createdAt: new Date().toISOString(),
    }
  }
}

